        } else m.grabTimer = Math.max(0, m.grabTimer - dt * 2);
      } else if (m.stage === 'escape' && marker && arrive(G, marker, marker.r)) {
        G.wanted = 0;
        G.cars = G.cars.filter((c) => c.kind !== 'police');
        G.bustTimer = 0;
